mapper.select:
select round(o.turnover, 2) as turnover, o.valid_order_count, ifnull( round( o.valid_order_count / nullif( ( select count(1) from orders where 1 = 1
), 0) ,2) , 0) as order_completion_rate, ifnull(round(o.turnover / nullif(o.valid_order_count, 0), 2), 0) as unit_price, ( select count(1) from user where 1 = 1
) as new_users from ( select ifnull(sum(total_amount), 0) as turnover, count(1) as valid_order_count from orders where status = 4
) o
